import axios from "axios"
import { useEffect, useState } from "react"
import { useAccount } from "wagmi"
import NftSkeleton from "./NftSkeleton"
import NftContainer from "./NftContainer"
import NftCard from "./NftCard"
import noImage from "../../../../../Images/no-image-available-icon-6.png"
import { Button } from "@mui/material"

interface Media {
  original_media_url: string
}

interface NftData {
  id: number
  name: string
  symbol: string
  media: Media
}

interface Data {
  result: NftData[]
}

interface ThemeMode {
  themeMode: boolean;
  tableMode: string
}


function NftsGrid({ themeMode, tableMode }: ThemeMode) {
  const [result, setResult] = useState<Data>({ result: [] });
  const { address, isConnected } = useAccount();
  const [count, setCount] = useState(0)
  const [isLoading, setIsLoading] = useState(true);
  const Skeletons = [1, 2, 3];
  const theme = {
    background: themeMode ? "#121212" : "#ffffff",
    color: themeMode ? "#fff" : "#000",
    skeletonColor: themeMode ? "#ffffff3b" : "#0000003b",
  }

  useEffect(() => {
    if (address === undefined) return;
    setIsLoading(true);
    async function getData() {
      const response = await axios.get(`http://localhost:5001/${tableMode}/`, {
        params: { address },
      });

      console.log(response.data);
      setResult(response.data);
      setIsLoading(false);
    }

    getData();
  }, [address, count, tableMode]);


  return (
    // check if the wallet is connected or not
    isConnected && <>
      {/* add a skeleton */}
      {isLoading && <NftContainer>
        {Skeletons.map(skeleton => <NftSkeleton theme={theme} />)}
      </NftContainer>}

      {/* show the nft data */}
      <NftContainer>
        {
          result.result.map(res =>
            <NftCard image={res.media !== undefined ? res.media.original_media_url : noImage} name={res.name} symbol={res.symbol} theme={theme} />
          )
        }
      </NftContainer>

      {/* show this element if the wallet was empty */}
      {!isLoading && result.result.length === 0 ? <div style={{ textAlign: "center", marginBlock: 100, backgroundColor: theme.background, width: "70%", marginInline: "auto", padding: 50, borderRadius: 20 }}>
        <h4 style={{ fontWeight: "bold", color: theme.color }}>No Nfts.</h4>
        <p style={{ color: theme.color }}>Don't see an Nft?</p>
        <Button onClick={() => {
          setCount(count + 1)
        }} variant="contained" sx={{ backgroundColor: themeMode ? "#653ba3" : "#31007a", "&:hover": { backgroundColor: themeMode ? "#653ba38d" : "#270061" } }}>Refresh</Button>
      </div> : null}

    </>
  )
}
export default NftsGrid