import { BsCurrencyExchange, BsFuelPump } from "react-icons/bs"
import { Link, useLocation } from "react-router-dom"

interface Props {
    themeMode: boolean
}

function MoodSelect({ themeMode }: Props) {

    const location = useLocation()

    return <>
        <div className='button-box d-lg-block mt-5'>
            <div id='btn' style={{ "left": location.pathname === "/" ? 0 : location.pathname === '/portfolio' ? 200 : 0, "backgroundColor": themeMode ? "#653ba3" : "#31007a" }}></div>
            <div className='d-flex justify-content-center'>
                <Link style={{ zIndex: 1 }} to='/'><button type='button' className='toggle-btn'><div className='d-flex justify-content-center'><BsCurrencyExchange size={20} className='mx-2' /> مبادله</div></button></Link>
                <Link style={{ zIndex: 1 }} to='/portfolio'><button type='button' className='toggle-btn'><div className='d-flex justify-content-center'><BsFuelPump size={20} className='mx-2' /> پرتفولیو</div></button></Link>
            </div>
        </div></>
}

export default MoodSelect