import { Card, CardContent, CardMedia, Typography } from '@mui/material'

interface Theme {
    background: string;
    color: string;
}

interface Props {
    image: string
    theme: Theme
    name: string
    symbol: string
}

function NftCard({ image, theme, name, symbol }: Props) {
    return (
        <Card sx={{ minWidth: 345, margin: 2, bgcolor: theme.background }}>
            <CardMedia
                sx={{ height: 300 }}
                image={image}
            />
            <CardContent>
                <Typography sx={{ color: theme.color }} gutterBottom variant="h5" component="div">
                    {name}
                </Typography>
                <Typography sx={{ color: theme.color }} variant="body2" color="text.secondary">
                    {symbol}
                </Typography>
            </CardContent>
        </Card>
    )
}

export default NftCard