import './App.css';
import { useState } from "react"
import Navbar from './components/Navbar';
import ExchangeSection from './components/ExchangeSection';
import BottomSection from './components/BottomSection';
import MoodSelect from './components/MoodSelect';
import { Route, Routes } from 'react-router-dom';
import Portfolio from './components/Portfolio/Portfolio';


function App() {

  const [darkMode, setDarkMode] = useState(true)
  // set the default background
  const previos_background = darkMode ? "light-background" : "dark-background"
  const background_color = darkMode ? "dark-background" : "light-background"

  const shapesColorsObject = {
    dark: {
      shape1: "#40128B",
      shape2: "#A555EC",
      shape3: "#0E185F",
      shape4: "#440A67",
    },
    light: {
      shape1: "#F7C8E0",
      shape2: "#ECF9FF",
      shape3: "#7286D3",
      shape4: "#F7C8E0",
    }
  }

  document.querySelector('body')?.classList.remove(previos_background)
  document.querySelector('body')?.classList.add(background_color)
  return (
    <>
      <div className={darkMode ? "background dark-background" : "background light-background"}>
        <svg className='shape-1' viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><path d="M89,63Q86,76,72.5,77.5Q59,79,49.5,80.5Q40,82,32.5,75Q25,68,19,59Q13,50,13.5,37Q14,24,26,19Q38,14,51,10Q64,6,70,18.5Q76,31,84,40.5Q92,50,89,63Z" stroke="none" stroke-width="0" fill={darkMode ? shapesColorsObject.dark.shape1 : shapesColorsObject.light.shape1}></path></svg>
        <svg className='shape-2' viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><path d="M62.5,71.5Q25,93,25,50Q25,7,62.5,28.5Q100,50,62.5,71.5Z" stroke="none" stroke-width="0" fill={darkMode ? shapesColorsObject.dark.shape2 : shapesColorsObject.light.shape2}></path></svg>
        <svg className='shape-3' viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><path d="M68,62Q69,74,56,76.5Q43,79,35,70Q27,61,20.5,47Q14,33,27,19.5Q40,6,60,9Q80,12,73.5,31Q67,50,68,62Z" stroke="none" stroke-width="0" fill={darkMode ? shapesColorsObject.dark.shape3 : shapesColorsObject.light.shape3}></path></svg>
        <svg className='shape-4' viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><path d="M68,62Q69,74,56,76.5Q43,79,35,70Q27,61,20.5,47Q14,33,27,19.5Q40,6,60,9Q80,12,73.5,31Q67,50,68,62Z" stroke="none" stroke-width="0" fill={darkMode ? shapesColorsObject.dark.shape4 : shapesColorsObject.light.shape4}></path></svg>
      </div>
      <Navbar themeMode={darkMode} setThemeMode={theme => setDarkMode(theme)} />
      <MoodSelect themeMode={darkMode} />
      <Routes>
        <Route path='/*' element={<ExchangeSection themeMode={darkMode} />} />
        <Route path='/portfolio' element={<Portfolio themeMode={darkMode} />} />
      </Routes>
      <BottomSection backgroundColor={darkMode ? "#121212" : "#ffffff"} backgroundColorHov={darkMode ? "#212121" : "#f9f9f9b7"} color={darkMode ? "#bcbcbc" : "#00000099"} />
    </>
  );
}

export default App;
