import { Button, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow } from "@mui/material"
import axios from "axios"
import { useEffect, useState } from "react"
import { useAccount } from "wagmi"
import TransactionsSkeleton from "./TransactionsSkeleton"


interface Type {
  type: string
}

interface Transaction {
  hash: string
  from_address: string
  to_address: string
  value: string
  internal_transactions: Type[]
}

interface TransactionResult {
  result: Transaction[]
}

interface Props {
  themeMode: boolean
  tableMode: string
}


function TransactionsTable({ themeMode, tableMode }: Props) {

  const [result, setResult] = useState<TransactionResult>({ result: [] });
  const { address, isConnected } = useAccount();
  const [isLoading, setIsLoading] = useState(true);
  const [count, setCount] = useState(0)
  const theme = {
    background: themeMode ? "#121212" : "#ffffff",
    color: themeMode ? "#fff" : "#000",
    border: themeMode ? " white" : "black",
    skeletonColor: themeMode ? "#ffffff3b" : "#0000003b",
  }

  useEffect(() => {
    if (address === undefined) return;
    setIsLoading(true);
    async function getData() {
      const response = await axios.get(`http://localhost:5001/${tableMode}/`, {
        params: { address },
      });

      console.log(response.data);
      setResult(response.data);
      setIsLoading(false);
    }

    getData();
  }, [address, count, tableMode]);


  return (
    isConnected && <>
      <TableContainer component={Paper} sx={{ width: "80%", marginInline: "auto", maxHeight: "400px", marginTop: 3, backgroundColor: theme.background, color: theme.color }}>
        <Table stickyHeader>
          <TableHead>
            <TableRow>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>هش</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>آدرس مبدا</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>آدرس مقصد</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>مقدار</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>نوع معامله</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {/* show the transaction data */}
            {result.result.map(res =>
              <TableRow
                sx={{ '&:last-child td, &:last-child th': { border: 0 } }}
              >
                <TableCell sx={{ color: theme.color }}>{res.hash ? res.hash : "Empty"}</TableCell>
                <TableCell sx={{ color: theme.color }}>{res.from_address ? res.from_address : "Empty"}</TableCell>
                <TableCell sx={{ color: theme.color }}>{res.to_address ? res.to_address : "Empty"}</TableCell>
                <TableCell sx={{ color: theme.color }}>{res.value ? res.value : "Empty"}</TableCell>
                <TableCell sx={{ color: theme.color }}>{res.internal_transactions[0] ? res.internal_transactions[0].type : "Empty"}</TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
        {/* show a skeleton while fetching data */}
        {isLoading && <TransactionsSkeleton theme={theme} />}

        {/* Show this element if the wallet has no transaction */}
        {!isLoading && result.result.length === 0 ? <div style={{ textAlign: "center", marginBlock: 100 }}>
          <h4 style={{ fontWeight: "bold" }}>No Activity.</h4>
          <p>Don't see anything ?</p>
          <Button onClick={() => {
            setCount(count + 1)
          }} variant="contained" sx={{ backgroundColor: themeMode ? "#653ba3" : "#31007a", "&:hover": { backgroundColor: themeMode ? "#653ba38d" : "#270061" } }}>Refresh</Button>
        </div> : null}
      </TableContainer>
    </>
  )
}

export default TransactionsTable