import { Box, Button } from "@mui/material";

interface Props {
    themeMode: boolean;
    tableMode: string;
    setTableMode: (mode: string) => void;
}

function DataSelector({ themeMode, tableMode, setTableMode }: Props) {


    return (
        <>
            <div className='data-selector d-lg-block mt-5'>
                <div className='d-flex justify-content-center'>
                    <Box sx={{ display: "flex", justifyContent: "center", flexDirection: { xs: "column", lg: "row" } }}>
                        <Button className={tableMode === "getwalletbalance" ? "selected-table-option-dark" : ""} sx={{ marginTop: { xs: 2, lg: 0 }, marginInline: 2, paddingInline: 10, borderRadius: 20, backgroundColor: themeMode ? "#653ba3" : "#31007a", "&:hover": { backgroundColor: themeMode ? "#653ba38d" : "#270061" } }} variant="contained" onClick={() => setTableMode("getwalletbalance")}>Tokens</Button>
                        <Button className={tableMode === "getwalletnft" ? "selected-table-option-dark" : ""} sx={{ marginTop: { xs: 2, lg: 0 }, marginInline: 2, paddingInline: 10, borderRadius: 20, backgroundColor: themeMode ? "#653ba3" : "#31007a", "&:hover": { backgroundColor: themeMode ? "#653ba38d" : "#270061" } }} variant="contained" onClick={() => setTableMode("getwalletnft")}>NFTs</Button>
                        <Button className={tableMode === "getwallettransactions" ? "selected-table-option-dark" : ""} sx={{ marginTop: { xs: 2, lg: 0 }, marginInline: 2, paddingInline: 10, borderRadius: 20, backgroundColor: themeMode ? "#653ba3" : "#31007a", "&:hover": { backgroundColor: themeMode ? "#653ba38d" : "#270061" } }} variant="contained" onClick={() => setTableMode("getwallettransactions")}>Transactions</Button>
                    </Box>
                </div>
            </div>

        </>
    )
}

export default DataSelector