import { useAccount, useConnect, useDisconnect } from "wagmi";
import { MetaMaskConnector } from "wagmi/connectors/metaMask";
import { Button } from '@mui/material'

interface Props {
    themeMode: boolean
}

function ConncetWaletPortfolio({ themeMode }: Props) {
    const { connectAsync } = useConnect();
    const { disconnectAsync } = useDisconnect();
    const { isConnected } = useAccount();
    const handleAuth = async () => {
        if (isConnected) {
            await disconnectAsync();
        }

        const { account, chain } = await connectAsync({
            connector: new MetaMaskConnector(),
        });
        const userData = { address: account, chainId: chain.id };

        console.log(userData);
    };

    return (
        !isConnected && <div style={{ display: "flex", justifyContent: "center" }}>
            <Button sx={{
                marginTop: 10,
                paddingInline: 9, paddingBlock: 2, backgroundColor: themeMode ? "#653ba3" : "#31007a", "&:hover": { backgroundColor: themeMode ? "#653ba38d" : "#270061" }, borderRadius: 50, fontWeight: "bold", boxShadow: themeMode
                    ? '3px 3px 56px 27px rgba(255,255,255,0.03)'
                    : '3px 3px 56px 27px rgba(0,0,0,0.1)',
            }} variant="contained" onClick={handleAuth}>{"Conncet wallet"}</Button>
        </div>
    );
}

export default ConncetWaletPortfolio;