import { createConfig, configureChains, WagmiConfig, mainnet } from "wagmi";
import { publicProvider } from "wagmi/providers/public";
import ConncetWaletPortfolio from "./ConncetWaletPortfolio";
import PortfolioTable from "./Table/PortfolioTable";

interface Props {
    themeMode: boolean;
}

function Portfolio({ themeMode }: Props) {

    const { publicClient, webSocketPublicClient } = configureChains(
        [mainnet],
        [publicProvider()],
    )

    const config = createConfig({
        publicClient,
        webSocketPublicClient,
    })
    return (
        <WagmiConfig config={config}>
            <PortfolioTable themeMode={themeMode} />
            <ConncetWaletPortfolio themeMode={themeMode} />
        </WagmiConfig>
    );
}

export default Portfolio;
