import { useState } from "react";
import DataSelector from "./DataSelector";
import NftsGrid from "./TableContent/Nft/NftsGrid";
import TokenTable from "./TableContent/Token/TokenTable";
import { useAccount } from "wagmi";
import TransactionsTable from "./TableContent/Transactions/TransactionsTable";


interface Theme {
    themeMode: boolean;
}


function PortfolioTable({ themeMode }: Theme) {
    const [tableMode, setTableMode] = useState("getwalletbalance")
    const { isConnected } = useAccount();

    return (
        <>
            {isConnected && <DataSelector themeMode={themeMode} tableMode={tableMode} setTableMode={(mode) => setTableMode(mode)} />}
            {tableMode === "getwalletbalance" ? <TokenTable themeMode={themeMode} tableMode={tableMode} /> : tableMode === "getwalletnft" ? <NftsGrid themeMode={themeMode} tableMode={tableMode} /> : tableMode === "getwallettransactions" ? <TransactionsTable themeMode={themeMode} tableMode={tableMode} /> : null}
        </>
    )
}

export default PortfolioTable;
