import Box from '@mui/material/Box';
import Avatar from '@mui/material/Avatar';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import IconButton from '@mui/material/IconButton';
import Tooltip from '@mui/material/Tooltip';
import React, { useState } from 'react';
import { BsList, BsDiscord, BsTelegram, BsTwitter, BsInfoCircleFill } from 'react-icons/bs'
import { Button, Dialog, DialogContent, DialogContentText, DialogTitle } from '@mui/material';
import logoImage from '../Images/sm_image.jpg';

interface Props {
    bgColor: string
    buttonBackground: string
    buttonBackgroundHover: string
    bgColorHover: string
    color: string
}


function DropdownMenu({ bgColor, buttonBackground, buttonBackgroundHover, bgColorHover, color }: Props) {
    const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);
    const open = Boolean(anchorEl);
    const handleClick = (event: React.MouseEvent<HTMLElement>) => {
        setAnchorEl(event.currentTarget);
    };
    const handleClose = () => {
        setAnchorEl(null);
    };

    const [openDialog, setOpenDialog] = useState(false);

    const handleClickOpen = () => setOpenDialog(true);
    const handleCloseDialog = () => setOpenDialog(false);


    return (
        <>
            <Box sx={{ display: 'flex', alignItems: 'center', textAlign: 'center' }}>
                <Tooltip title="Menu">
                    <IconButton
                        onClick={handleClick}
                        size="small"
                        sx={{ ml: 2 }}
                        aria-controls={open ? 'account-menu' : undefined}
                        aria-haspopup="true"
                        aria-expanded={open ? 'true' : undefined}
                    >
                        <Avatar sx={{ width: 40, height: 40, bgcolor: "transparent" }}><BsList size={35} fontWeight={"bold"} color={color} /></Avatar>
                    </IconButton>
                </Tooltip>
            </Box>
            <Menu
                anchorEl={anchorEl}
                id="account-menu"
                open={open}
                onClose={handleClose}
                onClick={handleClose}
                PaperProps={{
                    elevation: 0,
                    sx: {
                        bgcolor: bgColor,
                        color: color,
                        borderRadius: 3,
                        padding: 1,
                        overflow: 'visible',
                        filter: 'drop-shadow(0px 2px 8px rgba(0,0,0,0.32))',
                        mt: 3,
                        '& .MuiAvatar-root': {
                            width: 32,
                            height: 32,
                            ml: -0.5,
                            mr: 1,
                        },
                        '&:before': {
                            content: '""',
                            display: 'block',
                            position: 'absolute',
                            top: 0,
                            right: 13,
                            width: 15,
                            height: 15,
                            bgcolor: bgColor,
                            transform: 'translateY(-50%) rotate(45deg)',
                            zIndex: 0,
                        },
                    },
                }}
                transformOrigin={{ horizontal: 'right', vertical: 'top' }}
                anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
            >
                <MenuItem component="a" href="https://www.google.com/" target="_blank" onClick={handleClose} sx={{ color: color, padding: 1, textAlign: 'left', margin: "4px", fontSize: 19, transition: "all 0.2s ease-in", "&:hover": { backgroundColor: bgColorHover, borderRadius: "5px" } }}>
                    <Box display="flex" justifyContent="space-around" alignItems="center">
                        <BsDiscord size={25} />
                        <Box marginRight={2} />
                        <span>Discord</span>
                        <Box marginRight={15} />
                    </Box>
                </MenuItem>
                <MenuItem component="a" href="https://www.google.com/" target="_blank" onClick={handleClose} sx={{ color: color, padding: 1, textAlign: 'left', margin: "4px", fontSize: 19, transition: "all 0.2s ease-in", "&:hover": { backgroundColor: bgColorHover, borderRadius: "5px" } }}>
                    <Box display="flex" justifyContent="space-around" alignItems="center">
                        <BsTelegram size={25} />
                        <Box marginRight={2} />
                        <span>Telegram</span>
                        <Box marginRight={15} />
                    </Box>
                </MenuItem>
                <MenuItem component="a" href="http://www.twitter.com/BlankProject_" target="_blank" onClick={handleClose} sx={{ color: color, padding: 1, textAlign: 'left', margin: "4px", fontSize: 19, transition: "all 0.2s ease-in", "&:hover": { backgroundColor: bgColorHover, borderRadius: "5px" } }}>
                    <Box display="flex" justifyContent="space-around" alignItems="center">
                        <BsTwitter size={25} />
                        <Box marginRight={2} />
                        <span>Twitter</span>
                        <Box marginRight={15} />
                    </Box>
                </MenuItem>
                <MenuItem component="a" onClick={handleClickOpen} sx={{ color: color, padding: 1, textAlign: 'left', margin: "4px", fontSize: 19, transition: "all 0.2s ease-in", "&:hover": { backgroundColor: bgColorHover, borderRadius: "5px" } }}>
                    <Box display="flex" justifyContent="space-around" alignItems="center">
                        <BsInfoCircleFill size={25} />
                        <Box marginRight={2} />
                        <span>درباره ما</span>
                        <Box marginRight={15} />
                    </Box>
                </MenuItem>
                <MenuItem sx={{ justifyContent: 'center', display: 'flex' }}>
                    <Button sx={{ backgroundColor: buttonBackground, color: "white", fontWeight: "600", borderRadius: "30px", padding: "14px 60px 12px 60px", "&:hover": { backgroundColor: buttonBackgroundHover } }}>Connect</Button>
                </MenuItem>
            </Menu>
            <Dialog sx={{ textAlign: "center", backgroundColor: "rgba(0, 0, 0, 0.404)" }} open={openDialog} onClose={handleCloseDialog} aria-labelledby="dialog-title">
                <Box sx={{ backgroundColor: bgColor, color: color }}>
                    <img src={logoImage} alt="" style={{ borderRadius: 100, width: 100, margin: 30 }} />
                    <DialogTitle sx={{ fontWeight: "bold" }} id="dialog-title">Blank Project</DialogTitle>
                    <DialogContent>
                        <DialogContentText sx={{ color: color }}>
                            پروژه Blank یک استارت آپ کوچیک در حوزه وب۳ و ارز های دیجیتاله
                            هدف این پروژه گسترش ، تولید و دسترسی آسون تر خدمات و ابزار های Web3 برای جامعه‌ی فارسی زبان و هموطن های عزیزمون و ساخت یک جامعه از علاقه مندان این ساختار جدیده
                            حتما در شبکه های اجتماعی ما رو دنبال کنید و نظرات خودتون رو به اشتراک بزارید.
                            امیدواریم با حمایت شما عزیزان این پروژه روز به روز بزرگتر بشه.
                        </DialogContentText>
                    </DialogContent>
                </Box>
            </Dialog>
        </>
    );
}

export default DropdownMenu