import { Fab, Tooltip } from "@mui/material"
import IconRating from "./IconRating"
import { BsEnvelopeFill } from 'react-icons/bs'

interface Props {
    // get the background color
    backgroundColor: string
    // get the hover background color 
    backgroundColorHov: string
    // get the color
    color: string
}


function BottomSection({ backgroundColor, backgroundColorHov, color }: Props) {
    return (
        <>
            <div className="d-flex justify-content-between align-items-center bottom-section">
                <div className="d-flex justify-content-between rounded rounded-2 py-2 px-4" style={{ backgroundColor: backgroundColor }}>
                    <div className="me-2 mt-1 py-1" style={{ color: color, fontWeight: "bold" }}>Feedback </div>
                    <IconRating color={color} />
                </div>
                <Tooltip title="به ما ایمیل بزنید">
                    <Fab color="primary" aria-label="Call" sx={{ backgroundColor: backgroundColor, "&:hover": { backgroundColor: backgroundColorHov } }}>
                        <BsEnvelopeFill size={20} color={color} />
                    </Fab>
                </Tooltip>
            </div>
        </>
    )
}

export default BottomSection