import { Tooltip } from "@mui/material"
import ImageLogo from "../Images/Logo.png"
import Logo from "./Logo"
import DropdownMenu from "./DropdownMenu"
import { BsMoonFill, BsSunFill } from "react-icons/bs"
import { WidgetWalletManagement } from "@lifi/widget"

interface Props {
    themeMode: boolean
    setThemeMode: (theme: boolean) => void
}

function Navbar({ themeMode, setThemeMode }: Props, { connect }: WidgetWalletManagement) {

    return (
        <div className='d-flex justify-content-between align-items-center mx-4 my-auto'>
            <div className='d-flex justify-content-center align-items-center'>
                <Logo src={ImageLogo} />
            </div>
            <div className='d-flex justify-content-center align-items-center mt-3'>
                {/* <Hidden only={"xs"}>
                    <Button onClick={() => connect()} sx={{ backgroundColor: themeMode ? "#653ba3" : "#31007a", color: "white", fontWeight: "bold", borderRadius: "30px", padding: "14px 25px 12px 25px", marginInline: "12px", "&:hover": { backgroundColor: themeMode ? "#653ba38d" : "#270061" } }}>Connect Wallet</Button>
                </Hidden> */}
                <Tooltip sx={{ zIndex: 5 }} title="Change the theme"><button className='theme-btn mx-2' onClick={() => setThemeMode(!themeMode)} style={{ "backgroundColor": themeMode ? "rgba(255, 255, 255, 0.12)" : "rgba(255, 255, 255, 1)", "boxShadow": themeMode ? "0px 1px 29px 1px rgba(255, 255, 255, 0.3)" : "0px 1px 29px 10px rgba(0, 0, 0, 0.3)" }}>{themeMode ? <BsSunFill size={22} /> : <BsMoonFill size={22} color='black' />}</button></Tooltip>
                <DropdownMenu bgColor={themeMode ? "#120f29" : "#FFFFFF"} color={themeMode ? "#FFFFFF" : "#000000"} bgColorHover={themeMode ? "rgba(255, 255, 255, 0.08)" : "rgba(0, 0, 0, 0.08)"} buttonBackground={themeMode ? "#653ba3" : "#31007a"} buttonBackgroundHover={themeMode ? "#653ba38d" : "#270061"} />
            </div>
        </div>

    )
}

export default Navbar