import { Button, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow } from "@mui/material"
import axios from "axios"
import { useEffect, useState } from "react"
import { useAccount } from "wagmi"
import TokensSkeleton from "./TokensSkeleton"
import noImage from "../../../../../Images/no-image-available-icon-6.png"


interface PriceData {
  usdPrice: number
}
interface TokenDataRespone {
  tokenName: string
  tokenSymbol: string
  tokenLogo: string
  value: string
  tokenDecimals: string
}
interface TokensData {
  fullData: PriceData;
  _data: TokenDataRespone
}

interface Data {
  result: TokensData[]
}

interface ThemeMode {
  themeMode: boolean;
  tableMode: string
}


function TokenTable({ themeMode, tableMode }: ThemeMode) {
  const [result, setResult] = useState<Data>({ result: [] });
  const { address, isConnected } = useAccount();
  const [isLoading, setIsLoading] = useState(true);
  const [count, setCount] = useState(0)
  const theme = {
    background: themeMode ? "#121212" : "#ffffff",
    color: themeMode ? "#fff" : "#000",
    border: themeMode ? " white" : "black",
    skeletonColor: themeMode ? "#ffffff3b" : "#0000003b",
  }

  useEffect(() => {
    if (address === undefined) return;
    setIsLoading(true);
    async function getData() {
      const response = await axios.get(`http://localhost:5001/${tableMode}/`, {
        params: { address },
      });

      console.log(response.data);
      setResult(response.data);
      setIsLoading(false);
    }

    getData();
  }, [address, count, tableMode]);




  return (
    isConnected && <>
      <TableContainer component={Paper} sx={{ width: "80%", marginInline: "auto", maxHeight: "400px", marginTop: 3, backgroundColor: theme.background, color: theme.color }}>
        <Table stickyHeader>
          <TableHead>
            <TableRow>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>لوگوی توکن</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>نام توکن</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>نماد توکن</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>تعداد</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>قیمت</TableCell>
              <TableCell sx={{ backgroundColor: theme.background, color: theme.color, borderColor: theme.border, fontWeight: "bold" }}>موجودی</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {result.result.map(res =>
              res.fullData && <TableRow
                sx={{ '&:last-child td, &:last-child th': { border: 0 } }}
              >
                <TableCell sx={{ color: theme.color }} component="th" scope="row">
                  <img src={res._data ? res._data.tokenLogo : noImage} style={{ borderRadius: 50, width: 40, height: 40, border: "none" }} alt="" />
                </TableCell>
                <TableCell sx={{ color: theme.color }}>{res._data ? res._data.tokenName : "-"}</TableCell>
                <TableCell sx={{ color: theme.color }}>{res._data ? res._data.tokenSymbol : "-"}</TableCell>
                <TableCell sx={{ color: theme.color }}>{res._data && parseInt(res._data.value) / (10 ** parseInt(res._data.tokenDecimals)) ? parseInt(res._data.value) / (10 ** parseInt(res._data.tokenDecimals)) : "-"}</TableCell>
                <TableCell sx={{ color: theme.color }}>{res.fullData ? `$ ${res.fullData.usdPrice}` : "-"}</TableCell>
                <TableCell sx={{ color: theme.color }}>{res._data && parseInt(res._data.value) / (10 ** parseInt(res._data.tokenDecimals)) ? `$ ${parseInt(res._data.value) / (10 ** parseInt(res._data.tokenDecimals)) * res.fullData.usdPrice}` : "-"}</TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
        {isLoading && <TokensSkeleton theme={theme} />}

        {!isLoading && result.result.length === 0 ? <div style={{ textAlign: "center", marginBlock: 100 }}>
          <h4 style={{ fontWeight: "bold" }}>Nothing.</h4>
          <p>Don't see anything ?</p>
          <Button onClick={() => {
            setCount(count + 1)
          }} variant="contained" sx={{ backgroundColor: themeMode ? "#653ba3" : "#31007a", "&:hover": { backgroundColor: themeMode ? "#653ba38d" : "#270061" } }}>Refresh</Button>
        </div> : null}
      </TableContainer>
    </>
  );
}

export default TokenTable