import { Box } from "@mui/material"
import { ReactNode } from "react";

interface Props {
    children: ReactNode
}

function NftContainer({ children }: Props) {
    return (
        <Box width={"90%"} marginX={"auto"} sx={{ display: "flex", justifyContent: "center", flexWrap: "wrap", marginTop: 5, borderRadiusl: 20 }}>
            {children}
        </Box>
    )
}

export default NftContainer