import { Card, CardContent, CardMedia, Skeleton, Typography } from "@mui/material"


interface Theme {
    skeletonColor: string
    background: string;
}

interface Props {
    theme: Theme;
}

function NftSkeleton({ theme }: Props) {
    return (
        <Card sx={{ minWidth: 345, margin: 2, bgcolor: theme.background, borderRadius: 3 }}>
            <CardMedia>
                <Skeleton variant="rounded" width={345} height={300} sx={{ bgcolor: theme.skeletonColor }} />
            </CardMedia>
            <CardContent>
                <Typography gutterBottom variant="h5" component="div">
                    <Skeleton
                        animation="wave"
                        height={10}
                        width="80%"
                        sx={{ marginBottom: 1, bgcolor: theme.skeletonColor }}
                    />
                </Typography>
                <Typography variant="body2" color="text.secondary">
                    <Skeleton
                        animation="wave"
                        height={10}
                        width="80%"
                        sx={{ marginBottom: 1, bgcolor: theme.skeletonColor }}
                    />
                </Typography>
            </CardContent>
        </Card>
    )
}

export default NftSkeleton